import{_ as n,l as o,o as e,c as l,v as t,p as s,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"高斯消元与主元","description":"","frontmatter":{"title":"高斯消元与主元","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gaussian-pivoting.md","filePath":"cs/gaussian-pivoting.md","lastUpdated":1789023840000}'),E={name:"cs/gaussian-pivoting.md"};function c(A,a,u,m,B,_){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="高斯消元与主元" tabindex="-1">高斯消元与主元 <a class="header-anchor" href="#高斯消元与主元" aria-label="Permalink to &quot;高斯消元与主元&quot;">​</a></h1><div class="epigraph"><p>消元用当前列的主元去除下面的行；主元过小则乘数过大，舍入被放大，交换行是在选一个后向更稳的消去顺序。</p><footer>—— 据 Golub and Van Loan, Matrix Computations；Trefethen and Bau, Numerical Linear Algebra；Higham, Accuracy and Stability of Numerical Algorithms 整理</footer></div><p>上一课<a href="/cs/summation-order">求和顺序</a>说明结合律失败时顺序即算法。本课不重讲 Kahan，也不从行列式公理另起。缺口是：线性方程 \\(Ax=b\\) 的消去是一长串乘加与减法，<strong>没有主元策略时，一次除以过小的对角元就会把前面的 \\(\\gamma_n\\) 与抵消同时放进来</strong>。这是「线性与根」课序的第一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>高斯消元把 \\(A\\) 变成 \\(PA=LU\\)（带行交换时）。每步用主元除该列下方，得到乘数，再从下面的行减去倍数。缺口因此不是「如何用手算 3×3」，而是<strong>主元选择属于稳定性</strong>：部分主元在当前列选绝对值最大者，避免乘数超过 1 的量级。完全主元还看后面的列，代价更高。无主元时，即使 \\(A\\) 可逆且良态，算法也可以不稳定。</p><p>求和课的「谁先加」在这里变成「哪一行当主元」。两者都是在浮点里选结合与缩放的顺序。本课只钉部分主元的动机；增长因子的最坏指数界是理论边角，实践中部分主元对多数矩阵够用。</p><h3 id="主元不是「让对角元非零就行」" tabindex="-1">主元不是「让对角元非零就行」 <a class="header-anchor" href="#主元不是「让对角元非零就行」" aria-label="Permalink to &quot;主元不是「让对角元非零就行」&quot;">​</a></h3><p>精确算术里，非零即可继续（必要时换行避免恰好为零）。浮点里「几乎为零」比恰好为零更危险：乘数巨大，一行被另一行的舍入噪声淹没，后向扰动 \\(\\Delta A\\) 不再是 \\(O(u)\\|A\\|\\)。把主元理解成「跳过零」会在近奇异或缩放差的列上翻车。行缩放、列缩放会改变「谁最大」，选主元前要先问范数是否可比。</p><p><span class="marginnote">Golub and Van Loan 把 GEPP 写成标准分解。Trefethen and Bau 用增长因子解释为何部分主元几乎总是稳定。Higham 给出后向误差与残量的关系。本课不把稀疏消元的填入展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第 \\(k\\) 步：在 \\(k:n\\) 行的第 \\(k\\) 列选最大绝对值，换行，除法得乘数，秩一更新右下角。回代解三角系，三角解本身通常后向稳定。选主元的比较是数据依赖的控制流，不能当成与 \\(A\\) 无关的固定顺序。</p>',11)),(e(),s(h,null,{default:r(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%9F%A9%E9%98%B5%20A%22%5D%20--%3E%20PIV%5B%22%E9%80%89%E4%B8%BB%E5%85%83%E5%B9%B6%E6%8D%A2%E8%A1%8C%22%5D%0A%20%20PIV%20--%3E%20MULT%5B%22%E4%B9%98%E6%95%B0%E7%AD%89%E4%BA%8E%20a_ik%20%E9%99%A4%E4%BB%A5%E4%B8%BB%E5%85%83%22%5D%0A%20%20MULT%20--%3E%20UPD%5B%22%E6%9B%B4%E6%96%B0%E5%8F%B3%E4%B8%8B%E8%A7%92%22%5D%0A%20%20UPD%20--%3E%20LU%5B%22%E5%BE%97%E5%88%B0%20L%20%E4%B8%8E%20U%22%5D%0A%20%20LU%20--%3E%20SUB%5B%22%E4%B8%89%E8%A7%92%E5%9B%9E%E4%BB%A3%E5%BE%97%20x%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>残量 \\(b-A\\hat x\\) 小支持后向稳定的叙事，不保证 \\(\\hat x\\) 接近 \\(x\\)——那要乘<a href="/cs/condition-number">条件数</a>。下一课才把 \\(\\kappa(A)\\) 用矩阵范数写严。</p><p>列主元不对称：它不交换列，因此不改变未知量顺序，实现简单。完全主元改变变量顺序，要记录列置换才能还原 \\(x\\)。实际稠密密集问题里部分主元几乎总够；刻意构造的增长反例存在，但不应当把它们当成拒绝 GEPP 的理由。实现还要注意：比较绝对值时要把已更新的元素拿来比，而不是用原始 \\(A\\) 的副本，否则选的不是当前消去步骤真正用到的主元。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>乘数有界则更新里的乘加接近普通内积的 \\(\\gamma_n\\) 图像。主元过小等于把一行放大再去减，噪声被放大，等价于给 \\(A\\) 一个不小的 \\(\\Delta A\\)。交换行不改变精确解（对 \\(b\\) 同步交换），只改变浮点路径。这与灾难抵消相同：代数等价，数值不等价。增长因子刻画 \\(|U|\\) 相对 \\(|A|\\) 能长多少；部分主元把它在实践中按住。</p><p>部分主元对付的是算法注入，不降低 \\(A\\) 的 \\(\\kappa\\)。近奇异矩阵上，即使 GEPP 后向稳定，解也可以没有一位正确——扰动课会把这句话写成定理。选主元带来的行交换必须同时作用于 \\(b\\)（或保存置换再作用于右端），否则 \\(LU\\) 与原问题对不上。对 SPD 矩阵，Cholesky 无主元在精确算术里稳定得多，因为结构挡住了增长；这不是「所有矩阵都可以不选主元」。稀疏矩阵的主元还要跟填入权衡，本课只取稠密默认：先稳，再谈稀疏策略。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Cholesky 对 SPD 的无主元合法性，只点名：结构可以代替选主元。下一课<a href="/cs/matrix-norm-perturb">矩阵范数与扰动</a>给 \\(\\kappa(A)\\) 与扰动定理。后课默认：GE 必须带主元策略；部分主元是默认稳定手段；残量小不等于解准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>消元顺序由主元决定；过小主元放大舍入。</li><li>部分主元限制乘数，追求后向稳定的 \\(LU\\)。</li><li>行交换不改精确解，改变浮点路径。</li><li>下一课用范数写清 \\(Ax=b\\) 的扰动。</li><li>出处：Golub and Van Loan；Trefethen and Bau；Higham。</li></ul>',9))])}const P=n(E,[["render",c]]);export{f as __pageData,P as default};
